const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');

// Set the canvas dimensions
canvas.width = 400;
canvas.height = 400;

// Define the physical constants
const g = 9.81; // acceleration due to gravity (m/s^2)
const l = 10; // length of the pendulum (m)
const m = 1; // mass of the pendulum (kg)

// Define the initial conditions
let theta0 = 0; // initial angle (radians)
let omega0 = 0; // initial angular velocity (rad/s)

// Define the simulation parameters
const dt = 0.01; // time step (s)
const tmax = 10; // maximum simulation time (s)

// Define the rendering parameters
const circleRadius = 5; // radius of the pendulum bob
const lineStrokeWidth = 2; // stroke width of the pendulum line

// Main simulation function
function simulate() {
  // Update the simulation time
  let t = 0;

  // Loop until the simulation reaches the maximum time
  while (t < tmax) {
    // Update the pendulum's state
    omega0 += (-g / l) * Math.sin(theta0) * dt;
    theta0 += omega0 * dt;

    // Draw the pendulum
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2 - l * Math.sin(theta0), circleRadius, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.lineWidth = lineStrokeWidth;
    ctx.strokeStyle = 'black';
    ctx.beginPath();
    ctx.moveTo(canvas.width / 2, canvas.height / 2);
    ctx.lineTo(canvas.width / 2, canvas.height / 2 - l * Math.sin(theta0));
    ctx.stroke();

    // Check if the pendulum has stopped
    if (Math.abs(omega0) < 0.01) {
      break;
    }

    // Update the simulation time
    t += dt;
  }
}

