Here is an example of an AWS Lambda function written in Go that deletes EBS Snapshots based on the "backup_type" tag:
```
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context, event map[string]string) (map[string]string, error) {
	sess, err := session.NewSession(&aws.Config{
		Region: aws.String("your-region")},
	)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS Snapshots with the specified tag
	params := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name:  aws.String("tag:backup_type"),
				Values: []string{"monthly", "daily", "weekly", "yearly"},
			},
		},
	}
	resp, err := ec2Svc.DescribeSnapshotsWithContext(ctx, params)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Group snapshots by backup_type
	snapshotsByType := make(map[string][]*ec2.Snapshot)
	for _, snap := range resp.Snapshots {
		for _, tag := range snap.Tags {
			if *tag.Key == "backup_type" {
				snapshotsByType[*tag.Value] = append(snapshotsByType[*tag.Value], snap)
				break
			}
		}
	}

	// Delete excess snapshots for each type
	for backupType, snaps := range snapshotsByType {
		switch backupType {
		case "monthly":
			// Keep the last 14 monthly snapshots
			if len(snaps) > 14 {
				snapsToClean := snaps[:len(snaps)-14]
				for _, snap := range snapsToClean {
					deleteEC2Snapshot(snapshot)
				}
			}
		case "daily":
			// Keep the last 10 daily snapshots
			if len(snaps) > 10 {
				snapsToClean := snaps[:len(snaps)-10]
				for _, snap := range snapsToClean {
					deleteEC2Snapshot(snap)
				}
			}
		case "weekly":
			// Keep the last 4 weekly snapshots
			if len(snaps) > 4 {
				snapsToClean := snaps[:len(snaps)-4]
				for _, snap := range snapsToClean {
					deleteEC2Snapshot(snap)
				}
			}
		case "yearly":
			// Keep only one yearly snapshot
			if len(snaps) > 1 {
				snapsToClean := snaps[:len(snaps)-1]
				for _, snap := range snapsToClean {
					deleteEC2Snapshot(snap)
				}
			}
		}
	}

	return nil, nil
}

func deleteEC2Snapshot(snap *ec2.Snapshot) {
	_, err := ec2Svc.DeleteSnapshotWithContext(context.Background(), &ec2.DeleteSnapshotInput{
		SnapshotId: aws.String(*snap.SnapshotId),
	})
	if err != nil {
		log.Println(err)
	}
}

func main() {
	lambda.Start(handler)
}
```
